// Headless runner: bun scripts/run-dsl.ts file.sand [steps] — prints an ASCII view of the grid.
import { readFileSync } from 'node:fs';
import { Parser } from '../src/parser/parser';
import { ASTBuilder } from '../src/ast/astBuilder';
import { validateAST } from '../src/ast/astValidator';
import { buildGame } from '../src/game/builder/builder';
import { createEngine } from '../src/game/game';
import { createEvaluator } from '../src/game/interpreter/interpreter';

const [file, stepsArg, setup] = process.argv.slice(2);
const src = readFileSync(file, 'utf8');
const program = new ASTBuilder().build(new Parser(src).parse());
validateAST(program);
const W = 48, H = 24;
const engine = createEngine(buildGame(program), { width: W, height: H }, createEvaluator());
console.log('elements:', engine.availableElements().join(', '));
if (setup) for (const cmd of setup.split(';')) { const [t, x, y, w = '1', h = '1'] = cmd.split(','); for (let i = 0; i < +w; i++) for (let j = 0; j < +h; j++) try { engine.place(t, +x + i, +y + j); } catch {} }
const steps = Number(stepsArg ?? 40);
let snap = engine.snapshot();
const t0 = performance.now();
for (let i = 0; i < steps; i++) snap = engine.step();
const ms = (performance.now() - t0) / steps;
const grid = Array.from({ length: H }, () => Array(W).fill('.'));
const counts: Record<string, number> = {};
for (const e of snap.elements) { grid[e.y][e.x] = e.elementType[0]; counts[e.elementType] = (counts[e.elementType] ?? 0) + 1; }
console.log(grid.map((r) => r.join('')).join('\n'));
console.log(counts, `${ms.toFixed(2)} ms/step`);
